CREATE TYPE "InventoryTrackingMode" AS ENUM ('NONE','BATCH','SERIAL');
CREATE TYPE "StockMovementType" AS ENUM ('OPENING','PURCHASE','PURCHASE_RETURN','SALE','SALES_RETURN','TRANSFER_IN','TRANSFER_OUT','ADJUSTMENT_IN','ADJUSTMENT_OUT');
CREATE TYPE "InventoryPriceType" AS ENUM ('RETAIL','WHOLESALE','CUSTOMER');
ALTER TABLE "account_settings" ADD COLUMN "negativeStockAllowed" BOOLEAN NOT NULL DEFAULT false;
ALTER TABLE "account_products" ADD COLUMN "barcode" VARCHAR(120), ADD COLUMN "hsnCode" VARCHAR(12), ADD COLUMN "trackInventory" BOOLEAN NOT NULL DEFAULT false, ADD COLUMN "trackingMode" "InventoryTrackingMode" NOT NULL DEFAULT 'NONE', ADD COLUMN "lowStockThreshold" DECIMAL(18,4) NOT NULL DEFAULT 0;
CREATE UNIQUE INDEX "account_products_companyId_barcode_key" ON "account_products"("companyId","barcode");
CREATE TABLE "warehouses" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"companyId" UUID NOT NULL,"branchId" UUID NOT NULL,"name" VARCHAR(160) NOT NULL,"code" VARCHAR(60) NOT NULL,"address" TEXT,"isDefault" BOOLEAN NOT NULL DEFAULT false,"isActive" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE UNIQUE INDEX "warehouses_companyId_id_key" ON "warehouses"("companyId","id"); CREATE UNIQUE INDEX "warehouses_companyId_branchId_code_key" ON "warehouses"("companyId","branchId","code"); CREATE INDEX "warehouses_companyId_branchId_isActive_idx" ON "warehouses"("companyId","branchId","isActive");
ALTER TABLE "warehouses" ADD CONSTRAINT "warehouses_company_branch_fk" FOREIGN KEY ("companyId") REFERENCES "companies"("id") ON DELETE RESTRICT; ALTER TABLE "warehouses" ADD CONSTRAINT "warehouses_branch_fk" FOREIGN KEY ("companyId","branchId") REFERENCES "branches"("companyId","id") ON DELETE RESTRICT;
CREATE TABLE "inventory_batches" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"companyId" UUID NOT NULL,"productId" UUID NOT NULL,"batchNumber" VARCHAR(100) NOT NULL,"manufacturedDate" DATE,"expiryDate" DATE,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP); CREATE UNIQUE INDEX "inventory_batches_companyId_id_key" ON "inventory_batches"("companyId","id"); CREATE UNIQUE INDEX "inventory_batches_company_product_batch_key" ON "inventory_batches"("companyId","productId","batchNumber"); ALTER TABLE "inventory_batches" ADD CONSTRAINT "inventory_batches_product_fk" FOREIGN KEY ("companyId","productId") REFERENCES "account_products"("companyId","id") ON DELETE RESTRICT;
CREATE TABLE "inventory_serial_numbers" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"companyId" UUID NOT NULL,"productId" UUID NOT NULL,"serialNumber" VARCHAR(160) NOT NULL,"expiryDate" DATE,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP); CREATE UNIQUE INDEX "inventory_serial_companyId_id_key" ON "inventory_serial_numbers"("companyId","id"); CREATE UNIQUE INDEX "inventory_serial_company_product_number_key" ON "inventory_serial_numbers"("companyId","productId","serialNumber"); ALTER TABLE "inventory_serial_numbers" ADD CONSTRAINT "inventory_serial_product_fk" FOREIGN KEY ("companyId","productId") REFERENCES "account_products"("companyId","id") ON DELETE RESTRICT;
CREATE TABLE "stock_movements" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"companyId" UUID NOT NULL,"branchId" UUID NOT NULL,"warehouseId" UUID NOT NULL,"productId" UUID NOT NULL,"movementType" "StockMovementType" NOT NULL,"quantity" DECIMAL(18,4) NOT NULL CHECK ("quantity">0),"unitCost" DECIMAL(18,4) NOT NULL CHECK ("unitCost">=0),"totalCost" DECIMAL(18,2) NOT NULL,"sourceType" VARCHAR(80) NOT NULL,"sourceId" VARCHAR(160) NOT NULL,"sourceLineId" UUID,"batchId" UUID,"serialNumberId" UUID,"reason" TEXT,"movementDate" DATE NOT NULL,"createdById" UUID NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP); CREATE UNIQUE INDEX "stock_movements_companyId_id_key" ON "stock_movements"("companyId","id"); CREATE UNIQUE INDEX "stock_movements_source_idempotency_key" ON "stock_movements"("companyId","sourceType","sourceId","sourceLineId","movementType"); CREATE INDEX "stock_movements_scope_idx" ON "stock_movements"("companyId","warehouseId","productId","movementDate"); ALTER TABLE "stock_movements" ADD CONSTRAINT "stock_movement_warehouse_fk" FOREIGN KEY ("companyId","warehouseId") REFERENCES "warehouses"("companyId","id") ON DELETE RESTRICT; ALTER TABLE "stock_movements" ADD CONSTRAINT "stock_movement_product_fk" FOREIGN KEY ("companyId","productId") REFERENCES "account_products"("companyId","id") ON DELETE RESTRICT; ALTER TABLE "stock_movements" ADD CONSTRAINT "stock_movement_branch_fk" FOREIGN KEY ("companyId","branchId") REFERENCES "branches"("companyId","id") ON DELETE RESTRICT;
CREATE TABLE "product_prices" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"companyId" UUID NOT NULL,"productId" UUID NOT NULL,"priceType" "InventoryPriceType" NOT NULL,"customerId" UUID,"rate" DECIMAL(18,2) NOT NULL CHECK ("rate">=0),"effectiveFrom" DATE,"effectiveTo" DATE,"isActive" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL); CREATE UNIQUE INDEX "product_prices_companyId_id_key" ON "product_prices"("companyId","id"); CREATE INDEX "product_prices_lookup_idx" ON "product_prices"("companyId","productId","priceType","customerId","isActive"); ALTER TABLE "product_prices" ADD CONSTRAINT "product_prices_product_fk" FOREIGN KEY ("companyId","productId") REFERENCES "account_products"("companyId","id") ON DELETE RESTRICT;
